query:
LOAD CSV WITH HEADERS FROM 'file:///students.csv' AS row
CREATE (:Etudiant {
    id: row.id,
    age: toInteger(row.age),
    filiere: row.filiere,
    annee: toInteger(row.annee),
    logement: row.logement,
    stress_score: toInteger(row.stress_score),
    consomme_cannabis: toLower(trim(row.consomme_cannabis)) IN ["true", "1", "oui"],
    frequence_cannabis: row.frequence_cannabis,
    date_import: date()
});

CREATE INDEX etudiant_id IF NOT EXISTS FOR (e:Etudiant) ON (e.id);

LOAD CSV WITH HEADERS FROM 'file:///groups.csv' AS row
CREATE (:Groupe {
    group_id: row.group_id,
    type: row.type,
    taille: toInteger(row.taille)
});

CREATE INDEX groupe_id IF NOT EXISTS FOR (g:Groupe) ON (g.group_id);

LOAD CSV WITH HEADERS FROM 'file:///friendships.csv' AS row
MATCH (a:Etudiant {id: row.source})
MATCH (b:Etudiant {id: row.target})
CREATE (a)-[:CONNAIT {
    type: row.type,
    intensite: toInteger(row.intensite),
    date_debut: date(),
    date_fin: null
}]->(b);
